mapper.select:
select P.PRODUCT_NUMBER, P.NAME, P.DESCRIPTION, P.PRICE, P.QUANTITY, P.CREATED_DATE from PRODUCT_TB P WHERE 1=1
AND (P.PRODUCT_NUMBER LIKE '%' || #{searchInput} || '%' OR P.NAME LIKE '%' || #{searchInput} || '%')
AND P.QUANTITY >= #{stock_min}
AND P.QUANTITY <= #{stock_max}
AND P.PRICE >= #{price_min}
AND P.PRICE <= #{price_max}
AND TRUNC(P.CREATED_DATE) >= TO_DATE(#{Issued_fr_date}, 'YYYY-MM-DD')
AND TRUNC(P.CREATED_DATE) <= TO_DATE(#{Issued_to_date}, 'YYYY-MM-DD')
AND P.PRODUCT_NUMBER IN ( SELECT M.PRODUCT_NUMBER FROM PRODUCT_CATEGORY_MAPPING_TB M JOIN PRODUCT_CATEGORY_TB C ON M.CATEGORY_ID = C.ID WHERE C.ID = #{category} )
AND P.PRODUCT_NUMBER IN ( SELECT S.PRODUCT_NUMBER FROM SALES_POST_TB S JOIN PRODUCT_TB P ON P.PRODUCT_NUMBER = S.PRODUCT_NUMBER WHERE S.STATUS = #{sale_status} )

SELECT id, name, category_code AS categoryCode, next_val
FROM PRODUCT_CATEGORY_TB
WHERE id = #{id}

mapper.update:
UPDATE PRODUCT_TB
SET
QUANTITY = #{productQuantity}
WHERE
PRODUCT_NUMBER = #{productNumber}

mapper.select:
SELECT *
FROM (
SELECT
a.*,
ROW_NUMBER() OVER (ORDER BY

	${orderByClause}


	TRANSACTION_DATE DESC

) AS row_num
FROM
STOCK_TRANSACTION_TB a
)
WHERE row_num BETWEEN #{offset}
AND #{offset} + #{pageSize} - 1

mapper.update:
update INQUIRIES_TB
set RESOLVED_YN = 'Y'
WHERE ID = #{inquiriesId}

mapper.select:
SELECT R.ID, R.SALES_POST_ID, R.CUSTOMER_ID, R.RATING, R.MESSAGE, R.CREATED_DATE, R.UPLOAD_DATE, R.REPLY_YN FROM REVIEW_TB R WHERE 1=1
AND TRUNC(R.CREATED_DATE) >= TO_DATE(#{register_fr_date}, 'YYYY-MM-DD')
AND TRUNC(R.CREATED_DATE) <= TO_DATE(#{register_to_date}, 'YYYY-MM-DD')
AND ( R.SALES_POST_ID IN ( SELECT S.ID FROM SALES_POST_TB S WHERE S.PRODUCT_NUMBER LIKE '%' || #{searchInput} || '%' ) OR R.SALES_POST_ID IN ( SELECT S.ID FROM SALES_POST_TB S WHERE S.TITLE LIKE '%' || #{searchInput} || '%' ) OR R.CUSTOMER_ID IN ( SELECT C.ID FROM CUSTOMER_TB C WHERE C.NICKNAME LIKE '%' || #{searchInput} || '%' ) )
AND R.REPLY_YN = #{replyYn}
AND R.RATING = #{rating}
AND R.REPLY_YN = #{replyYn}

SELECT
D.ID, D.ONSALE_YN, D.NAME, D.TYPE, D.START_DATE, D.END_DATE,
D.DISCOUNT_TYPE, D.DISCOUNT_VALUE, D.MAX_DISCOUNT, D.DESCRIPTION,
D.MIN_PRICE
FROM DISCOUNT_TB D
WHERE 1=1

	AND TRUNC(D.START_DATE) <=
	TO_DATE(#{register_to_date},
	'YYYY-MM-DD')
	AND TRUNC(D.END_DATE) >=
	TO_DATE(#{register_fr_date},
	'YYYY-MM-DD')


	AND D.MIN_PRICE >= #{fr_min}


	AND D.MIN_PRICE <= #{to_min}


	AND D.MAX_DISCOUNT >= #{fr_max}


	AND D.MAX_DISCOUNT <= #{to_max}


	AND D.ONSALE_YN = #{onsaleYn}


	AND D.DISCOUNT_TYPE = #{discountType}


	AND D.TYPE = #{type}

SELECT USERNAME
FROM USER_TB
WHERE ID = #{userId}

SELECT COUNT(*)
FROM PRODUCT_TB
WHERE NAME LIKE #{keyword}

SELECT COUNT(*)
FROM CUSTOMER_TB
WHERE NAME LIKE #{keyword}

mapper.update:
UPDATE
DISCOUNT_TARGET_TB
SET TARGET_TYPE = #{targetType}, TARGET_ID =
#{targetId}
WHERE id = #{id}

mapper.select:
SELECT C.* FROM COUPON_ISSUANCE_TB C JOIN DISCOUNT_TB D ON C.DISCOUNT_ID = D.ID JOIN CUSTOMER_TB CU ON C.CUSTOMER_ID = CU.ID JOIN USER_TB U ON CU.USER_ID = U.ID WHERE 1=1
AND C.DISCOUNT_ID IN ( SELECT C.DISCOUNT_ID FROM COUPON_ISSUANCE_TB C JOIN DISCOUNT_TB D ON D.ID = C.DISCOUNT_ID WHERE TRUNC(D.START_DATE) <= TO_DATE(#{discount_to_date}, 'YYYY-MM-DD') AND TRUNC(D.END_DATE) >= TO_DATE(#{discount_fr_date}, 'YYYY-MM-DD') )
AND TRUNC(C.ISSUED_AT) >= TO_DATE(#{register_fr_date}, 'YYYY-MM-DD') AND TRUNC(C.ISSUED_AT) <= TO_DATE(#{register_to_date}, 'YYYY-MM-DD')
AND ( D.NAME LIKE '%' || #{searchInput} || '%' OR U.USERNAME LIKE '%' || #{searchInput} || '%' OR TO_CHAR(C.COUPON_NUMBER) LIKE '%' || #{searchInput} || '%' )
AND D.DISCOUNT_TYPE = #{discountType}
AND C.USED_YN = #{usedYn}

SELECT DISTINCT O.* FROM ORDER_TB O JOIN ORDER_STATUS_TB T ON T.ORDER_ID = O.ID JOIN ORDER_DETAIL_TB D ON D.ORDER_ID = O.ID JOIN CUSTOMER_TB C ON C.ID = O.IDENTIFIER_ID JOIN USER_TB U ON U.ID = C.USER_ID JOIN SALES_POST_TB S ON S.ID = D.SALES_POST_ID WHERE 1=1
AND O.PAYMENT_TYPE = #{paymentType}
AND T.ORDER_STATUS = #{orderStatus}
AND TRUNC(O.ORDER_DATE) >= TO_DATE(#{order_fr_date}, 'YYYY-MM-DD') AND TRUNC(O.ORDER_DATE) <= TO_DATE(#{order_to_date}, 'YYYY-MM-DD')
AND (S.TITLE LIKE '%' || #{searchInput} || '%' OR U.USERNAME LIKE '%' || #{searchInput} || '%' OR C.NAME LIKE '%' || #{searchInput} || '%' OR O.ORDER_NUMBER LIKE '%' || #{searchInput} || '%')

SELECT O.* FROM ORDER_TB O JOIN ORDER_STATUS_TB T ON O.ID = T.ORDER_ID WHERE 1 = 1
AND T.ORDER_STATUS IN
#{stat}

SELECT DISTINCT O.* FROM ORDER_TB O JOIN ORDER_STATUS_TB T ON T.ORDER_ID = O.ID JOIN ORDER_DETAIL_TB D ON D.ORDER_ID = O.ID JOIN CUSTOMER_TB C ON C.ID = O.IDENTIFIER_ID JOIN USER_TB U ON U.ID = C.USER_ID JOIN SALES_POST_TB S ON S.ID = D.SALES_POST_ID WHERE 1=1
AND T.ORDER_STATUS IN
#{stat}
AND O.PAYMENT_TYPE = #{paymentType}
AND TRUNC(O.ORDER_DATE) >= TO_DATE(#{order_fr_date}, 'YYYY-MM-DD') AND TRUNC(O.ORDER_DATE) <= TO_DATE(#{order_to_date}, 'YYYY-MM-DD')
AND (S.TITLE LIKE '%' || #{searchInput} || '%' OR U.USERNAME LIKE '%' || #{searchInput} || '%' OR C.NAME LIKE '%' || #{searchInput} || '%' OR O.ORDER_NUMBER LIKE '%' || #{searchInput} || '%')

